<script setup lang="ts">
import { Image, ArrowUpRight, Search } from 'lucide-vue-next'
interface Asset { id: string; mime: string; size: number; url: string; ownerId: string | null; ownerTitle: string; references: { id: string; title: string }[]; public: boolean }
const { data: assets, error, status: loadStatus, refresh } = await useAdminData<Asset[]>('/api/admin/assets', [], { lazy: true })
const loading = computed(() => loadStatus.value === 'idle' || loadStatus.value === 'pending')
const filter = ref('all'); const query = ref('')
const list = computed(() => (assets.value || []).filter(a => (filter.value === 'all' || (filter.value === 'public' ? a.public : !a.public)) && a.ownerTitle.includes(query.value)))
useSeoMeta({ title: '附件 — XIAOJUESHI' })
</script>
<template><AdminShell><main class="workspace-page"><div class="workspace-page-heading"><div><div class="page-eyebrow">ASSETS</div><h1>附件</h1><p>查看图片来源、引用情况和实际公开状态。</p></div></div><div class="content-toolbar"><div class="segmented"><button v-for="option in [{ id: 'all', name: '全部' }, { id: 'public', name: '公开' }, { id: 'private', name: '未公开' }]" :key="option.id" :class="{ active: filter === option.id }" @click="filter = option.id">{{ option.name }}</button></div><label class="workspace-search"><Search :size="16" /><input v-model="query" placeholder="按来源内容搜索" aria-label="搜索附件" /></label></div><LoadingSkeleton v-if="loading" variant="assets" label="正在加载附件列表" /><div v-else-if="error" class="notice" role="alert">加载失败。<button @click="refresh()">重试</button></div><div v-if="!loading && !error" class="asset-grid"><article v-for="asset in list" :key="asset.id" class="asset-card"><a :href="asset.url" target="_blank" rel="noopener" class="asset-preview"><img :src="asset.url" :alt="asset.ownerTitle" loading="lazy" /></a><div class="asset-info"><span class="visibility-badge" :class="asset.public ? 'public' : 'private'">{{ asset.public ? '已公开' : '未公开' }}</span><span>{{ (asset.size / 1024).toFixed(1) }} KB · {{ asset.mime.split('/')[1]?.toUpperCase() }}</span><h2>{{ asset.ownerTitle }}</h2><p>{{ asset.references.length }} 项内容引用。{{ asset.public ? '公开版本正在使用此图片。' : '需要管理员登录才能访问。' }}</p><NuxtLink v-if="asset.ownerId" :to="`/admin/write?id=${asset.ownerId}`" class="text-link">查看来源内容 <ArrowUpRight :size="14" /></NuxtLink></div></article></div><div v-if="!list.length && !error && !loading" class="empty-state"><Image :size="28" /><h2>暂无附件</h2><p>在编辑器中上传图片后，会出现在这里。</p></div></main></AdminShell></template>
